import{_ as r,p as e,q as a,s as t,R as d,t as s,Y as p,n}from"./framework-e1bed10d.js";const c="/my-blog/assets/008_01-5ced7985.png",h="/my-blog/assets/008_02-43706e58.png",u="/my-blog/assets/008_03-eed251c8.png",i={},q=t("h1",{id:"信贷的商业模式与资金闭环",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#信贷的商业模式与资金闭环","aria-hidden":"true"},"#"),d(" 信贷的商业模式与资金闭环")],-1),l={href:"https://mp.weixin.qq.com/s?__biz=MzIzNzQ5NjU5NQ==&mid=2247484355&idx=1&sn=4f791fc1db7b008c65b7c3d99a9a9f6a&chksm=e8c6f3bfdfb17aa916a09a9fa0bd20a53c7bd01852dea58e09b7009d32655a83ca7c2ed10381",target:"_blank",rel:"noopener noreferrer"},_=p('<hr><h2 id="五、信贷的商业模式与资金闭环" tabindex="-1"><a class="header-anchor" href="#五、信贷的商业模式与资金闭环" aria-hidden="true">#</a> 五、信贷的商业模式与资金闭环</h2><h3 id="一-钱从哪来-四种资金模式" tabindex="-1"><a class="header-anchor" href="#一-钱从哪来-四种资金模式" aria-hidden="true">#</a> （一）钱从哪来：四种资金模式</h3><p>前面讲了信贷赚钱的姿势，这一节讲资金从哪来。资金模式，是信贷机构最根本的分界线，它决定了系统要不要&quot;操心钱从哪来&quot;。我在自序里反复讲过一个观察：同样做信贷，大行和互金平台的系统为什么差那么多？最致命的分界就在资金。大行有存款池，放贷的钱是客户存进来的，系统只需要管&quot;放出去、收回来&quot;；互金和民营银行没有低成本负债，放贷的钱要靠外部机构、ABS、联合贷供给，系统就必须管&quot;钱从哪来、怎么分、怎么还&quot;。这两种系统，一个简单一个复杂，不是技术差距，是资金模式决定的。这一节，就把这四种模式讲清楚。</p><p>第一种，自有资金模式。机构用自有资本和负债（存款、拆借）放贷，银行是典型，系统相对简单，不需要复杂的资金路由（见图1-14）。</p><p>第二种，批发资金模式。机构从银行或同业批发资金，再以零售方式放给客户，小贷公司、消费金融公司是典型。系统需要管理资金成本和期限匹配，但比联合贷简单，不需要分账。</p><p>第三种，联合贷资金模式。两家及以上按比例共同出资、共担风险收益，系统核心是&quot;分账&quot;。监管红线：合作机构出资比例不得低于30%。</p><p>第四种，ABS出表模式。贷款打包成资产支持证券卖给投资者，资产从表内转出、盘活资金，是最考验数据一致性的一块（见图1-14）。</p><p><img src="'+c+'" alt="图片"></p><p><strong>图1-14 信贷四种资金模式：复杂度从左到右递增</strong></p><p><img src="'+h+'" alt="图片"></p><p><strong>图1-15 ABS 相关对象：从预选到存续的全流程体系</strong></p><table><thead><tr><th><strong>检查项</strong></th><th><strong>底线要求</strong></th></tr></thead><tbody><tr><td>第一查·资金去向</td><td>每笔放款、还款、退款的资金轨迹完整可追踪，无“三不知”（从哪来、到哪去、被谁挪）</td></tr><tr><td>第二查·支付路由</td><td>放款/还款渠道按资金方、成本、成功率、限额规则路由，路由变更留痕</td></tr><tr><td>第三查·存管/托管</td><td>客户资金进存管账户，平台不触碰客户资金，资金流与信息流分离</td></tr><tr><td>第四查·电子账户划转</td><td>放款资金秒过划转到借款人电子账户、受托支付到收款方，资金不过夜、不落地</td></tr><tr><td>第五查·备付金</td><td>有支付牌照的机构，客户备付金集中存管、不得挪用</td></tr><tr><td>第六查·对账</td><td>日终对账全覆盖，账实不符当日查明、当日处理</td></tr></tbody></table><h3 id="二-资金闭环监管-钱必须全程可追踪" tabindex="-1"><a class="header-anchor" href="#二-资金闭环监管-钱必须全程可追踪" aria-hidden="true">#</a> （二）资金闭环监管：钱必须全程可追踪</h3><p>信贷系统里有一个高频词叫&quot;资金闭环&quot;。这个词的意思很朴素：资金从放款到回收，每一笔都要在系统里留下完整、可追踪的轨迹，不能出现&quot;钱从哪来不知道、钱到哪去不知道&quot;的情况。</p><p>不同业务形态，资金闭环的侧重点不一样：零售信贷看&quot;钱&quot;的流向，供应链金融看&quot;贸易&quot;的真假。</p><p><img src="'+u+'" alt="图片"></p><p><strong>图1-16 资金闭环监管的系统实现：四个抓手</strong></p><p>先讲零售信贷。资金闭环监管的系统实现，主要有四个抓手。</p><p>第一个，支付路由。放款走哪个渠道、还款从哪个渠道扣，按资金方成本/成功率/限额综合选择，资金流第一道闸门，持续调优的动态过程。</p><p>第二个，银行存管/托管。资金放在银行存管账户，平台不触碰客户资金，资金流与信息流分离，业务系统与存管系统对账是日常大事故高发点。</p><p>第三个，电子账户秒过划转。资金从资金方秒过到借款人电子账户再受托支付，还款反向划回，资金不过夜、不落地，从机制上杜绝资金池和挪用。</p><p>第四个，备付金管理。有支付牌照的机构客户备付金集中存管、不能挪用。核心原则：凡是客户的钱，都必须有清晰归属和去向。</p><p>为了让你对&quot;资金闭环&quot;这四个字有画面感，我走一遍互金平台最常见的一笔助贷放款。借款人从APP提交申请、通过审批后，平台发起放款：资金方账户的钱，通过存管银行的支付路由，秒过划转到借款人在存管银行开的电子账户，再受托支付到商户账户；还款时，从借款人电子账户反向划回，整个过程资金不过夜、不落地，每一步都有系统记录。</p><p>我在给互金平台做资金架构时反复强调一句话：资金闭环不是合规部门的要求，是系统的物理属性。资金路由、存管、划转、对账，每一个环节的设计，都是为了回答同一个问题：这笔钱现在在哪、要往哪去、账上记的是什么。</p><p>再讲供应链金融。它的资金闭环逻辑和零售不一样：零售盯的是&quot;钱有没有被挪用&quot;，供应链盯的是&quot;贸易是不是真的&quot;。贸易真假怎么验？靠&quot;流&quot;的交叉验证。这个概念一直在升级，每一步都是监管在堵套利漏洞：最早是三流合一：物流、资金流、信息流。物流看货真的发了没有，有发货单、物流轨迹、入库单；资金流看钱真的转了没有，有银行流水、付款凭证；信息流看信息真的记了没有，有订单、合同、系统记录。三流能对上，基本能排除大部分空单。后来监管要求四流合一，加上商流。光有三流还不够，因为有人可以造假物流、造假流水，但交易本身是假的。商流就是真实贸易背景：谁卖给谁、卖的是什么、为什么买、交易价格合不合理。加上商流，就是要证明这买卖真的做了，不是为了融资编出来的。金税四期之后升级到七流合一，再拆细出合同流、发票流、业务流。合同流看签约主体、标的、金额、期限和实际业务是不是一致，防阴阳合同；发票流看开票方、受票方、品名、数量、金额和合同及实际交付是不是一致，防虚开发票；业务流看业务全过程有没有记录，从立项、执行、交付到验收，每个环节有没有留痕，不是只有发票没有过程。七流全对上，才敢说这贸易是真的。</p><p>对程序员来说，&quot;流&quot;越多，系统复杂度越高：三流合一只要对接仓储、支付；四流合一还要对接核心企业ERP；七流合一还要对接发票系统、业务管理系统。我在TCL金融做产业金融的时候，最深的体会是：供应链金融的系统难点不在资金路由，而在&quot;流&quot;的验真。</p><p><strong>表1-2 资金闭环合规底线清单</strong></p><table><thead><tr><th>检查项</th><th>具体要求</th></tr></thead><tbody><tr><td>资金归属清晰</td><td>每一笔客户资金都明确归属，不能混同</td></tr><tr><td>资金去向清晰</td><td>每一笔资金流转都有明确目的地，不能不明不白</td></tr><tr><td>资金路径可追溯</td><td>从放款到回收，每一步都有系统记录，可查可追</td></tr><tr><td>账实相符</td><td>系统账面记录和银行实际流水必须一致，不能对账不平</td></tr><tr><td>对账及时</td><td>日终对账、月度对账、季度对账，不能攒着一起对</td></tr><tr><td>异常可预警</td><td>资金异常流动、大额划转、可疑路径，系统自动报警</td></tr></tbody></table><p>这六查合起来，就是资金闭环的合规底线：每一笔资金都有归属、有去向、有痕迹。做这件事的意义，不只是应付监管，当&quot;钱从哪来、到哪去、账上记什么&quot;每一环都说得清，系统本身才经得起任何一次审计。</p>',30);function b(g,m){const o=n("ExternalLinkIcon");return e(),a("div",null,[q,t("blockquote",null,[t("p",null,[d("公众号：侃西东　·　发布日期：2026-09-20　·　"),t("a",l,[d("微信原文"),s(o)])])]),_])}const x=r(i,[["render",b],["__file","008.html.vue"]]);export{x as default};
